import React from 'react';
import {AbsoluteFill,interpolate,Easing,clamp,useS,en,DUR,FONT} from './kit';
/**
 * VARIADO: THE 8-MINUTE DELAY — directed 2.5D edition.
 * Shot-based science animation, full-screen cuts, tracking camera, macro views.
 * 30 fps via isolated playbook30 runner. Every shot keyed to narration words.
 */
const G='#ffd18a', B='#5fe4ff', W='#f1f6ff', INK='#020713';
const P=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],clamp);
const E=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const PE=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.out(Easing.cubic)});
const VIS=(s:number,a:number,b:number)=>Math.max(0,Math.min(P(s,a,a+.25),1-P(s,b-.20,b)));
const S={
  disappear:en('desapareciera'),
  min:en('ocho'),
  light:en('luz'),
  earth:en('Tierra'),
  last:en('último'),
  ray:en('rayo'),
  exist:en('existiera'),
  gravity:en('gravedad'),
  instant:en('instante'),
  info:en('información'),
  travel:en('viaja'),
  speed:en('velocidad'),
  equal:en('Así'),
  orbit:en('órbita'),
  minutes:en('minutos',2),
  arrival:en('llegara'),
  discover:en('descubrirías'),
  lastEight:en('Ocho',2),
  end:en('universo')
};
const cuts=[0,en('Durante'),en('El'),en('Y'),en('La'),en('Así'),en('Solo'),S.lastEight,DUR];
const dust=Array.from({length:124},(_,i)=>({x:(i*191+87)%1080,y:(i*419+37)%1920,r:(i%4)*.7+1.2,tw:(i*13)%87}));
const Label:React.FC<{top?:number;title:string;sub?:string;tint?:string;scale?:number}>=({top=255,title,sub,tint=W,scale=1})=>
 <div style={{position:'absolute',top,left:55,right:55,textAlign:'center',transform:'scale('+scale+')'}}>
  <div style={{fontFamily:FONT,color:tint,fontSize:65,letterSpacing:-2,fontWeight:900,lineHeight:1.08,textShadow:'0 8px 25px #000b'}}>{title}</div>
  {sub&&<div style={{fontFamily:FONT,color:'#b5cada',fontSize:26,letterSpacing:3,fontWeight:700,marginTop:13,textShadow:'0 4px 22px #000'}}>{sub}</div>}
 </div>;
const Halo:React.FC<{x:number;y:number;r:number;c:string;opacity?:number}>=({x,y,r,c,opacity=.3})=>
 <circle cx={x} cy={y} r={r} stroke={c} strokeWidth="2" fill="none" opacity={opacity}/>;
const Sun:React.FC<{x:number;y:number;r:number;t:number;dark?:number}>=({x,y,r,t,dark=0})=>
 <g opacity={1-dark}>
  <defs>
   <radialGradient id="sunCore" cx="34%" cy="25%"><stop stopColor="#fff9d3"/><stop offset=".33" stopColor="#ffe6a0"/><stop offset=".74" stopColor="#ff9f38"/><stop offset="1" stopColor="#bb3c1d"/></radialGradient>
   <radialGradient id="sunGlow"><stop stopColor="#ffba47" stopOpacity=".45"/><stop offset="1" stopColor="#ff8e2b" stopOpacity="0"/></radialGradient>
  </defs>
  <circle cx={x} cy={y} r={r*2.4} fill="url(#sunGlow)" opacity=".9"/>
  {Array.from({length:20},(_,i)=>{const a=i*Math.PI/10+t*.09;const k=Math.sin(t*1.3+i)*r*.1;return <path key={i} d={'M '+(x+Math.cos(a)*r*.94)+' '+(y+Math.sin(a)*r*.94)+' Q '+(x+Math.cos(a+.1)*(r*1.25+k))+' '+(y+Math.sin(a+.1)*(r*1.25+k))+' '+(x+Math.cos(a+.25)*r*1.06)+' '+(y+Math.sin(a+.25)*r*1.06)} stroke={i%2===0?'#ffbf63':'#ff783e'} strokeWidth={7+i%3*2} fill="none" opacity=".64"/>})}
  <circle cx={x} cy={y} r={r} fill="url(#sunCore)" stroke="#ffe7a7" strokeWidth="2"/>
  {Array.from({length:8},(_,i)=><path key={i} d={'M '+(x-r*.7)+' '+(y+(i-3.5)*r*.17)+' Q '+x+' '+(y+(i-3.5)*r*.1+Math.sin(t+i)*r*.14)+' '+(x+r*.7)+' '+(y+(i-3.5)*r*.12)} stroke="#ffefb8" strokeWidth="3" opacity=".26" fill="none"/>)}
 </g>;
const Earth:React.FC<{x:number;y:number;r:number;t:number;shade?:number;spin?:number}>=({x,y,r,t,shade=0,spin=1})=>
 <g>
  <defs><radialGradient id="earthOcean" cx="28%" cy="18%"><stop stopColor="#adf9ff"/><stop offset=".32" stopColor="#2da9db"/><stop offset=".8" stopColor="#164578"/><stop offset="1" stopColor="#091c3a"/></radialGradient><clipPath id="earthClip"><circle cx={x} cy={y} r={r}/></clipPath></defs>
  <circle cx={x} cy={y} r={r*1.15} stroke="#9cf7ff" strokeWidth={5} opacity=".2" fill="none"/>
  <circle cx={x} cy={y} r={r} fill="url(#earthOcean)" stroke="#84d8ff" strokeWidth="2"/>
  <g clipPath="url(#earthClip)" transform={'translate('+((t*spin*12)% (r*1.1)-r*.55)+' 0)'}>
   <path d={'M '+(x-r*.55)+' '+(y-r*.65)+' q '+(r*.65)+' '+(-r*.25)+' '+(r*.78)+' '+(r*.18)+' l '+(-r*.3)+' '+(r*.3)+' l '+(r*.15)+' '+(r*.28)+' l '+(-r*.45)+' '+(r*.2)+' l '+(-r*.26)+' '+(-r*.18)+' Z'} fill="#67cb9b" opacity=".8"/>
   <path d={'M '+(x-r*.10)+' '+(y+r*.1)+' q '+(r*.8)+' '+(-r*.12)+' '+(r*.76)+' '+(r*.5)+' l '+(-r*.5)+' '+(r*.44)+' l '+(-r*.38)+' '+(-r*.35)+' Z'} fill="#8bdd9f" opacity=".84"/>
   <path d={'M '+(x-r*.85)+' '+(y+r*.55)+' q '+(r*.55)+' '+(-r*.35)+' '+(r*.64)+' '+(r*.11)+' l '+(-r*.28)+' '+(r*.35)+' Z'} fill="#81dc8d" opacity=".8"/>
  </g>
  <circle cx={x} cy={y} r={r} fill="#06142e" opacity={shade*.94}/>
  <path d={'M '+(x-r*.7)+' '+(y-r*.3)+' A '+r+' '+r+' 0 0 1 '+(x+r*.4)+' '+(y+r*.77)} stroke="#d5ffff" strokeWidth="3" fill="none" opacity={.55-shade*.25}/>
 </g>;
const Bg:React.FC<{s:number;speed?:number;keyframe?:number}>=({s,speed=1,keyframe=0})=>
 <AbsoluteFill style={{background:'radial-gradient(circle at 53% 45%,#162b51 0%,#071328 48%,#02040c 100%)'}}>
  <svg width="1080" height="1920" viewBox="0 0 1080 1920" style={{position:'absolute'}}>
   {dust.map((d,i)=><circle key={i} cx={(d.x+s*speed*(.8+(i%4)*.2))%1080} cy={((d.y+s*speed*(1.6+(i%5)))-keyframe*20)%1920} r={d.r} fill={i%11===0?G:'#bce5ff'} opacity={.14+.2*(.5+.5*Math.sin(s*1.8+d.tw))}/>)}
  </svg>
 </AbsoluteFill>;
const Hud:React.FC<{step:number;lead:string;detail:string}>=({step,lead,detail})=>
 <div style={{position:'absolute',top:86,left:58,right:58,display:'flex',justifyContent:'space-between',fontFamily:FONT,fontWeight:800,fontSize:24,letterSpacing:3,color:'#b1d2e7'}}>
 <span>VARIADO <span style={{color:G}}>•</span> CIENCIA</span><span>{String(step).padStart(2,'0')}/08</span>
 </div>;
const Card:React.FC<{t:string;sub?:string;x?:number;y?:number;accent?:string;opacity?:number}>=({t,sub,x=540,y=1155,accent=G,opacity=1})=>
 <g opacity={opacity}><rect x={x-340} y={y-63} width={680} height={sub?155:112} rx="23" fill="#051026" fillOpacity=".94" stroke={accent} strokeOpacity=".66" strokeWidth="2"/>
 <text x={x} y={y+13} textAnchor="middle" fill={accent} fontFamily={FONT} fontSize="64" fontWeight="900">{t}</text>
 {sub&&<text x={x} y={y+72} textAnchor="middle" fill="#d0e6f5" fontFamily={FONT} fontSize="23" fontWeight="650" letterSpacing="3">{sub}</text>}</g>;
const CutFlash:React.FC<{s:number;start:number;col?:string}>=({s,start,col='#d8f7ff'})=> {
 const d=s-start;return d>=0&&d<.2?<AbsoluteFill style={{background:col,opacity:.2*(1-d/.2)}}/>:null;
};
// Shot 1: immediate tangible climax: entire solar disk implodes on "desapareciera".
// A dolly from near the star into the empty space it leaves.
const Shot1:React.FC<{s:number}>=({s})=>{
 const p=PE(s,S.disappear,S.disappear+.46);
 const zoom=1+.24*P(s,0,S.disappear)-.43*p;
 const shrink=1-P(s,S.disappear,S.disappear+.34);
 const shock=P(s,S.disappear,S.disappear+.68);
 const streak=Array.from({length:32},(_,i)=>i*Math.PI*2/32);
 return <AbsoluteFill><Bg s={s} speed={.9}/><svg viewBox="0 0 1080 1920" width="1080" height="1920" style={{transformOrigin:'540px 850px',transform:'scale('+zoom+')'}}>
 <Sun x={540} y={850} r={360*shrink} t={s} dark={p}/>
 {p>.02&&<g><circle cx="540" cy="850" r={360*shock} fill="#050916" stroke={G} strokeWidth={8*(1-shock)+2} opacity={1-.5*shock}/>
 {streak.map((a,i)=><path key={i} d={'M '+(540+Math.cos(a)*380*shock)+' '+(850+Math.sin(a)*380*shock)+' L '+(540+Math.cos(a)*(480+700*shock))+' '+(850+Math.sin(a)*(480+700*shock))} stroke={i%2?G:'#e8effe'} strokeWidth={Math.max(0,9*(1-shock))} opacity={1-shock}/>)}</g>}
 <g opacity={P(s,0,.3)}><Earth x={930} y={1320} r={69} t={s}/></g>
 </svg>
 <Label top={245} title="¿Y SI EL SOL..." sub="UNA PREGUNTA QUE CAMBIA TODO" tint={W}/>
 <div style={{position:'absolute',top:1240,left:120,right:120,textAlign:'center',fontFamily:FONT,fontWeight:950,fontSize:79,color:G,textShadow:'0 5px 25px #000'}}>{s<S.disappear?'DESAPARECIERA?':p<.85?'DESAPARECE': '¿LO NOTARÍAS?'}</div>
 <CutFlash s={s} start={S.disappear} col="#fff1cc"/>
 </AbsoluteFill>
};
// Shot 2: orbital scale revealed; we physically ride a tiny photon toward Earth.
const Shot2:React.FC<{s:number}>=({s})=>{
 const t=P(s,cuts[1],cuts[2]);const fly=E(s,S.light,cuts[2]);
 const cam=-240*fly, zm=1+.32*fly;
 return <AbsoluteFill><Bg s={s} speed={5}/>
 <svg viewBox="0 0 1080 1920" width="1080" height="1920" style={{transform:'translateX('+cam+'px) scale('+zm+')',transformOrigin:'540px 920px'}}>
  <path d="M 160 930 C 360 740 610 750 970 940" stroke={G} strokeWidth="58" opacity=".18" fill="none"/>
  <path d="M 160 930 C 360 740 610 750 970 940" stroke={G} strokeWidth="4" strokeDasharray="15 28" strokeDashoffset={-s*130} opacity=".8" fill="none"/>
  <Sun x={160} y={930} r={160} t={s} dark={1}/>
  <circle cx="160" cy="930" r="140" fill="#0c1422" stroke="#61758c" strokeWidth="3"/>
  <Earth x={970} y={940} r={112} t={s}/>
  {Array.from({length:20},(_,i)=>{const k=((i/20)+fly)%1;const x=160+810*k,y=930-190*Math.sin(Math.PI*k);return <g key={i}><circle cx={x} cy={y} r={7+(i%3)} fill="#fff4c6" opacity={.25+.75*k}/><circle cx={x} cy={y} r={15} fill={G} opacity=".11"/></g>})}
  <circle cx={160+810*fly} cy={930-190*Math.sin(Math.PI*fly)} r="32" fill="#fff9db" stroke={G} strokeWidth="7"/>
  <circle cx={160+810*fly} cy={930-190*Math.sin(Math.PI*fly)} r="78" fill={G} opacity=".17"/>
 </svg>
 <Label top={255} title="8 MINUTOS 20 SEGUNDOS" sub="LA LUZ TODAVÍA ESTÁ VIAJANDO" tint={G}/>
 <div style={{position:'absolute',left:140,right:140,top:1225,height:18,background:'#23425a',borderRadius:20}}>
  <div style={{height:'100%',width:(fly*100)+'%',background:G,borderRadius:20,boxShadow:'0 0 22px #fdd478'}}/>
 </div>
 <div style={{position:'absolute',top:1275,left:180,right:180,textAlign:'center',fontFamily:FONT,color:'#e4f5ff',fontSize:27,letterSpacing:3}}>DEL SOL HACIA LA TIERRA</div>
 <CutFlash s={s} start={cuts[1]}/>
 </AbsoluteFill>;
};
// Shot 3: insert from inside the flying beam with a tracking POV, then widen to Earth's cloud layers.
const Shot3:React.FC<{s:number}>=({s})=>{
 const fly=E(s,S.ray,cuts[3]-.28);const scan=P(s,S.last,S.ray+.4);
 return <AbsoluteFill><Bg s={s} speed={16}/>
 <svg width="1080" height="1920" viewBox="0 0 1080 1920" style={{position:'absolute'}}>
 <defs><linearGradient id="raygold"><stop stopColor="#ffeaab"/><stop offset="1" stopColor="#f8a439" stopOpacity="0"/></linearGradient></defs>
 {Array.from({length:22},(_,i)=>{const p=(i/22+fly*1.6)%1;const y=(i*121+fly*1100)%1920;const x=540+(i%2?-1:1)*(140+350*p);return <path key={i} d={'M '+x+' '+(y+360*p)+' L '+(540+(x-540)*.4)+' '+(y-170*p)} stroke={i%3?G:B} strokeWidth={2+i%3*2} opacity={.06+.48*p}/>})}
 <g transform={'translate('+(480-140*fly)+' '+(730-160*fly)+') scale('+(1+fly*2.1)+')'}>
  <circle cx="0" cy="0" r="86" fill={G} opacity=".16"/>
  <circle cx="0" cy="0" r="30" fill="#fff"/>
  <circle cx="0" cy="0" r="14" fill="#fffed5"/>
  {Array.from({length:11},(_,i)=><line key={i} x1="-120" y1={(i-5)*18} x2="-370" y2={(i-5)*28} stroke={G} strokeWidth="6" opacity=".2"/>)}
 </g>
 <g transform={'translate(610 '+(1960-1150*fly)+') scale('+(1+fly*1.7)+')'}>
  <Earth x={0} y={500} r={475} t={s}/>
  <path d="M -400 360 Q -140 30 230 195" stroke="#c5ffff" strokeWidth="20" opacity=".26" fill="none"/>
  <path d="M -430 430 Q 20 150 300 270" stroke="#fff" strokeWidth="11" opacity=".24" fill="none"/>
 </g>
 </svg>
 <Label top={240} title="EL ÚLTIMO RAYO" sub="SIGUE EN CAMINO" tint={G}/>
 <div style={{position:'absolute',top:1260,left:120,right:120,display:'flex',gap:14,alignItems:'center',justifyContent:'center',fontFamily:FONT,color:W,fontWeight:900,fontSize:36}}><span style={{color:G}}>SOL:</span> YA NO EXISTE <span style={{color:B}}>LUZ:</span> SÍ</div>
 <CutFlash s={s} start={cuts[2]} col="#fceabe"/>
 </AbsoluteFill>
};
// Shot 4: camera tilts down into a real animated spacetime grid.
// Gravity propagates via wavefronts from the erased Sun, not instantaneously.
const Shot4:React.FC<{s:number}>=({s})=>{
 const pull=E(s,cuts[3],S.gravity+.3),waves=P(s,S.gravity,cuts[4]-.25);
 return <AbsoluteFill><Bg s={s} speed={1.9}/>
 <svg width="1080" height="1920" viewBox="0 0 1080 1920" style={{position:'absolute'}}>
 <g transform={'translate(0 '+(160-210*pull)+') perspective(600)'} opacity={.65+.2*pull}>
   {Array.from({length:17},(_,i)=><path key={i} d={'M '+(i*78-84)+' 525 Q '+(540+(i*78-624)*.34)+' '+(915+Math.sin(s*2+i)*8)+' '+(i*78-84)+' 1400'} fill="none" stroke={B} strokeWidth="2" opacity=".18"/> )}
   {Array.from({length:14},(_,i)=><path key={'h'+i} d={'M 20 '+(535+i*66)+' Q 540 '+(460+i*75+95*Math.exp(-Math.abs(i-5)*.45))+' 1060 '+(535+i*66)} fill="none" stroke={B} strokeWidth="2" opacity={.16+.04*(i%2)}/>)}
 </g>
 <circle cx="295" cy="884" r={116+pull*15} fill="#080e1a" stroke="#45627e" strokeWidth="5"/>
 <ellipse cx="295" cy="884" rx="190" ry="64" stroke={G} strokeWidth="4" fill="none" opacity={.15}/>
 <Earth x={832} y={875} r={99} t={s}/>
 {Array.from({length:7},(_,i)=>{const d=(waves*720-i*115);return d>0?<circle key={i} cx="295" cy="884" r={d} stroke={B} strokeWidth={12-i%3*2} fill="none" opacity={Math.max(0,.58-d/1200)}/>:null})}
 <path d="M 295 885 Q 540 1080 832 875" stroke={G} strokeWidth="5" strokeDasharray="22 15" fill="none" opacity=".55"/>
 </svg>
 <Label title="Y LA GRAVEDAD..." sub="TAMPOCO CAMBIA AL INSTANTE" tint={B}/>
 <div style={{position:'absolute',top:1250,left:128,right:128,fontFamily:FONT,fontSize:31,color:W,textAlign:'center',fontWeight:700,letterSpacing:1}}>EL CAMBIO SE PROPAGA COMO UNA SEÑAL</div>
 <CutFlash s={s} start={cuts[3]}/>
 </AbsoluteFill>
};
// Shot 5: a real visual comparison is run, not just labels.
// Equal speeds, one destination; camera tracks paired progress bars.
const Shot5:React.FC<{s:number}>=({s})=>{
 const go=E(s,S.travel,cuts[5]-.25),showText=P(s,S.speed,S.speed+.4);
 return <AbsoluteFill><Bg s={s} speed={3.7}/>
 <Label top={228} title="DOS SEÑALES" sub="MISMA VELOCIDAD, MISMO DESTINO" tint={W}/>
 <svg width="1080" height="1920" viewBox="0 0 1080 1920">
  {Array.from({length:2},(_,i)=>{const y=i===0?760:1050,c=i?B:G;return <g key={i}>
   <rect x="120" y={y-93} width="840" height="190" rx="30" fill="#071425" stroke={c} strokeWidth="2" strokeOpacity=".34"/>
   <text x="165" y={y-43} fill={c} fontFamily={FONT} fontWeight="900" fontSize="31">{i?'GRAVEDAD':'LUZ'}</text>
   <path d={'M 165 '+(y+26)+' H 910'} stroke={c} strokeWidth="7" opacity=".18" strokeLinecap="round"/>
   <path d={'M 165 '+(y+26)+' H '+(165+745*go)} stroke={c} strokeWidth="9" strokeLinecap="round"/>
   <circle cx={165+745*go} cy={y+26} r={i?23:17} fill={i?'#081e35':'#fff6dd'} stroke={c} strokeWidth="6"/>
   {i===1&&Array.from({length:3},(_,j)=><circle key={j} cx={165+745*go} cy={y+26} r={29+j*25} stroke={B} strokeWidth="3" fill="none" opacity={.4-j*.1}/>)}
   {i===0&&Array.from({length:4},(_,j)=><path key={j} d={'M '+(165+745*go-j*21)+' '+(y+26)+' h -50'} stroke={G} strokeWidth="3" opacity={.4-j*.09}/>)}
   <circle cx="910" cy={y+26} r="26" fill="#27657b" stroke="#9fe4ff" strokeWidth="4"/>
  </g>})}
 </svg>
 <div style={{position:'absolute',top:1260,left:135,right:135,textAlign:'center',fontFamily:FONT,fontSize:73,fontWeight:900,color:G,opacity:showText,transform:'scale('+(0.8+.2*showText)+')'}}>VELOCIDAD DE LA LUZ</div>
 <div style={{position:'absolute',top:1360,left:180,right:180,height:2,background:'#28405e'}}/>
 <CutFlash s={s} start={cuts[4]}/>
 </AbsoluteFill>
};
// Shot 6: dynamic orbit visualization. The EARTH travels a short true-to-scale arc,
// while camera pivots around its globe and the clock advances metaphorically.
const Shot6:React.FC<{s:number}>=({s})=>{
 const p=P(s,cuts[5],cuts[6]),move=E(s,S.orbit,cuts[6]);
 const ex=764+35*move,ey=970-35*move;
 const dolly=1+.4*move;
 return <AbsoluteFill><Bg s={s} speed={2.5}/>
 <svg viewBox="0 0 1080 1920" width="1080" height="1920" style={{transformOrigin:'670px 950px',transform:'translateX('+(-100*move)+'px) scale('+dolly+')'}}>
 <ellipse cx="350" cy="930" rx="680" ry="340" stroke="#42617a" strokeWidth="12" fill="none" opacity=".45" transform="rotate(-12 350 930)"/>
 <ellipse cx="350" cy="930" rx="680" ry="340" stroke={G} strokeWidth="8" fill="none" strokeDasharray="25 40" strokeDashoffset={-s*45} opacity=".6" transform="rotate(-12 350 930)"/>
 <circle cx="110" cy="930" r="112" fill="#0a1019" stroke="#5d6872" strokeWidth="3"/>
 <path d={'M '+(ex-80)+' '+(ey+90)+' q 50 75 165 0'} stroke={G} strokeWidth="8" fill="none" opacity={.4}/>
 <Earth x={ex} y={ey} r={175} t={s} spin={1.8}/>
 <path d={'M '+(ex-180)+' '+(ey+30)+' L '+(ex-260)+' '+(ey+60)} stroke={B} strokeWidth={3} opacity=".6"/>
 <path d={'M '+(ex+190)+' '+(ey-30)+' L '+(ex+295)+' '+(ey-80)} stroke={B} strokeWidth={3} opacity=".6"/>
 </svg>
 <Label title="LA TIERRA SIGUE..." sub="TODAVÍA NO RECIBIÓ LA INFORMACIÓN" tint={B}/>
 <div style={{position:'absolute',top:1240,left:120,right:120,border:'2px solid #84c9dd',background:'#04152ee8',borderRadius:22,padding:'22px 22px',display:'flex',justifyContent:'space-between',alignItems:'center'}}>
 <div style={{fontFamily:FONT,fontSize:28,color:'#bdd8e7',fontWeight:700}}>SIGUE SU ÓRBITA</div>
 <div style={{fontFamily:FONT,fontSize:47,color:G,fontWeight:900}}>{('0'+Math.floor(p*8)).slice(-2)+':'+('0'+Math.floor((p*20)%60)).slice(-2)}</div></div>
 <CutFlash s={s} start={cuts[5]}/>
 </AbsoluteFill>
};
// Shot 7: the news FINALLY arrives. A travelling wave slams Earth,
// sparks hit atmosphere; the orbit direction switches to a tangent.
const Shot7:React.FC<{s:number}>=({s})=>{
 const approach=E(s,cuts[6],S.arrival+.4);
 const hit=PE(s,S.arrival,S.arrival+.28);
 const dark=E(s,S.discover,cuts[7]-.2);
 const ep=640,ey=905;
 return <AbsoluteFill><Bg s={s} speed={6}/>
 <svg width="1080" height="1920" viewBox="0 0 1080 1920">
  {Array.from({length:8},(_,i)=>{const x=-320+900*approach-i*85;return <path key={i} d={'M '+x+' 280 Q '+(x+130)+' 880 '+x+' 1480'} stroke={i%2?B:'#eefcff'} strokeWidth={8} fill="none" opacity={.06+.08*i} />})}
  <g transform={'translate('+(-35*dark)+' '+(-45*dark)+') scale('+(1+.13*dark)+')'} style={{transformOrigin:'640px 905px'}}>
  <Earth x={ep} y={ey} r={258} t={s} shade={dark} spin={1.1}/>
  </g>
  {hit>.001&&<g>{Array.from({length:7},(_,i)=><circle key={i} cx={ep} cy={ey} r={270+hit*(120+i*70)} stroke={i%2?G:B} strokeWidth={8} fill="none" opacity={(1-hit)*.6}/>)}</g>}
